def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    sources = []
    source_cells = set()

    # Each contiguous horizontal run along a border is a pattern to repeat.
    for r in (0, h - 1):
        c = 0
        while c < w:
            if grid[r][c] == 0:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != 0:
                c += 1
            if c - start >= 2:
                seq = grid[r][start:c]
                sources.append(seq)
                source_cells.update((r, j) for j in range(start, c))

    # Every other nonzero cell identifies the pattern containing its color;
    # place that pattern horizontally with the matching element on the marker.
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value == 0 or (r, c) in source_cells:
                continue
            for seq in sources:
                if value in seq:
                    k = seq.index(value)
                    left = c - k
                    for i, color in enumerate(seq):
                        x = left + i
                        if 0 <= x < w:
                            out[r][x] = color
                    break
    return out
